code='''from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(x for r in grid for x in r).most_common(1)[0][0]
    comps=[]; seen=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=bg and (r,c) not in seen:
        st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
         a,b=st.pop(); comp.append((a,b))
         for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
          x,y=a+da,b+db
          if 0<=x<h and 0<=y<w and grid[x][y]!=bg and (x,y) not in seen:
           seen.add((x,y)); st.append((x,y))
        comps.append(comp)
    main=max(comps,key=len); rs=[x for x,y in main]; cs=[y for x,y in main]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    mainset=set(main); markers=[x for x in comps if x is not main]
    target={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if (r,c) not in mainset}
    def norm(s):
      a=min(x for x,y in s); b=min(y for x,y in s); return frozenset((x-a,y-b) for x,y in s)
    def turns(s):
      ans=[]; cur=norm(s)
      for _ in range(4):
       if cur not in ans: ans.append(cur)
       cur=norm({(y,-x) for x,y in cur})
      return ans
    opts=[]
    for i,m in enumerate(markers):
      color=grid[m[0][0]][m[0][1]]; placements=[]
      for shape in turns(m):
       for anchor in target:
        for sr,sc in shape:
         dr,dc=anchor[0]-sr,anchor[1]-sc
         p=frozenset((r+dr,c+dc) for r,c in shape)
         if p<=target: placements.append((p,color))
      opts.append(placements)
    bycell={p:[] for p in target}
    for i,ps in enumerate(opts):
     for p,col in ps:
      for cell in p: bycell[cell].append((i,p,col))
    assignment={}; used=set(); filled={}
    def solve():
     if len(assignment)==len(target): return True
     cell=min((x for x in target if x not in assignment),key=lambda x:sum(i not in used and not (p&assignment.keys()) for i,p,c in bycell[x]))
     for i,p,col in bycell[cell]:
      if i not in used and not (p&assignment.keys()):
       used.add(i)
       for x in p: assignment[x]=i; filled[x]=col
       if solve(): return True
       used.remove(i)
       for x in p: del assignment[x]; del filled[x]
     return False
    if not solve(): raise ValueError('No tiling')
    return [[grid[r][c] if (r,c) in mainset else filled[(r,c)] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
'''
